'use client'

import React, { useState, useEffect } from 'react'
import dynamic from 'next/dynamic'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
// import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Card, CardContent } from '@/components/ui/card'
import { ChevronRight, Upload, ImageIcon, X, Loader2 } from 'lucide-react'
import Image from 'next/image'
import { z } from 'zod'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import {
  useAddProduct,
  useGetCategories,
  useGetSubCategories,
} from '@/lib/productsApi'
import { Checkbox } from '@/components/ui/checkbox'
import {
  useUpdateProduct,
  useGetSingleProductById,
  useGetColors,
} from '@/lib/handleAllGetRequests'
import { useRouter } from 'next/navigation'

// --------------------
// Schema
// --------------------
export const productSchema = z.object({
  title: z.string().min(1, 'Title is required'),

  msrp: z.number().positive('MSRP must be a positive number'),
  moq: z.number().int().positive('MOQ must be a positive integer'),
  unitPrice: z.number().positive('Unit Price must be a positive number'),
  discountPrice: z
    .number()
    .positive('Discount price must be a positive number')
    .optional(),
  quantity: z.number().int().positive('Quantity must be a positive integer'),
  description: z.string().min(1, 'Description is required'),
  action: z.enum(['inactive', 'active']),
  category: z.any(),
  subCategory: z.any(),
  productType: z.string().min(1, 'Product type is required'),
  brand: z.string().min(1, 'Brand is required'),
  // colors: z.array(z.string()).min(1, 'Select at least one color'),
  colors: z.array(z.string()).min(1, 'Select at least one color'),
  sizes: z.array(z.string()).min(1, 'Select at least one size'),
})
interface AddProductProps {
  editId?: string
}

export type ProductFormData = z.infer<typeof productSchema>

// --------------------
// Tiptap Editor Setup
// --------------------
const TiptapEditor = dynamic(
  () => import('../_components/tiptap-editor').then((mod) => mod.default),
  {
    ssr: false,
    loading: () => (
      <div className="border border-[#B6B6B6] rounded-md p-4 min-h-[250px]">
        Loading editor...
      </div>
    ),
  }
)

type UploadedImage = {
  file: File
  preview: string
  isExisting: boolean
}

const sizeOptions = ['XS', 'S', 'M', 'L', 'XL', 'XXL']

// Default form values
const defaultFormValues: ProductFormData = {
  title: '',

  msrp: 0,
  moq: 0,
  unitPrice: 0,
  discountPrice: undefined,
  quantity: 0,
  description: '',
  action: 'inactive',
  category: '',
  subCategory: '',
  productType: '',
  brand: '',
  colors: [],
  sizes: [],
}

// --------------------
// AddProduct Component
// --------------------
export default function AddProduct({ editId }: AddProductProps) {
  const router = useRouter()
  const [uploadedImages, setUploadedImages] = useState<UploadedImage[]>([])
  const [selectedColors, setSelectedColors] = useState<string[]>([])
  const [selectedSizes, setSelectedSizes] = useState<string[]>([])
  const [selectedCategoryId, setSelectedCategoryId] = useState<string>('')
  const [availableProductTypes, setAvailableProductTypes] = useState<string[]>(
    []
  )
  const [isDataLoaded, setIsDataLoaded] = useState(false)

  // API calls
  const { data: categoriesData, isLoading: categoriesLoading } =
    useGetCategories()
  const { data: subCategoriesData, isLoading: subCategoriesLoading } =
    useGetSubCategories(selectedCategoryId)

  // Get single product for editing
  const {
    data: singleProductData,
    // refetch: getSingleProduct,
    isLoading: singleProductLoading,
  } = useGetSingleProductById(editId)

  const { data: colorData, isLoading: colorsLoading } = useGetColors()

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    reset,
    formState: { errors },
  } = useForm<ProductFormData>({
    resolver: zodResolver(productSchema),
    defaultValues: defaultFormValues,
  })

  // // colors console
  // console.log('colors', selectedColors)
  // console.log('colors data', colorData?.data)

  // Success callback function for both add and update
  const handleSuccess = () => {
    reset(defaultFormValues)
    setUploadedImages([])
    setSelectedColors([])
    setSelectedSizes([])
    setSelectedCategoryId('')
    setAvailableProductTypes([])
    setIsDataLoaded(false)

    // Clean up image preview URLs
    uploadedImages.forEach((image) => {
      if (image.preview && !image.isExisting) {
        URL.revokeObjectURL(image.preview)
      }
    })

    // Navigate back to products list after successful operation

    // router.push('/seller-dashboard/products')
    router.back()
  }

  // React Query mutation hooks
  const { mutate: addProduct, isPending: isAddingProduct } = useAddProduct({
    onSuccess: handleSuccess,
    onError: (error) => {
      console.error('Error adding product:', error)
    },
  })

  const { mutate: updateProduct, isPending: isUpdatingProduct } =
    useUpdateProduct({
      onSuccess: handleSuccess,
      onError: (error) => {
        console.error('Error updating product:', error)
      },
    })

  const isPending = isAddingProduct || isUpdatingProduct

  // Load product data for editing
  useEffect(() => {
    if (editId && singleProductData?.data && !isDataLoaded) {
      const product = singleProductData.data

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const colorIds = product.colors?.map((c: any) => c._id) || []

      reset({
        title: product.title || '',
        msrp: product.msrp || 0,
        moq: product.moq || 0,
        unitPrice: product.unitPrice || 0,
        discountPrice: product.discountPrice || 0,
        quantity: product.quantity || 0,
        description: product.description || '',
        action: product.action || 'inactive',
        category: product.category?._id || '',
        subCategory: product.subCategory?._id || '',
        productType: product.productType || '',
        brand: product.brand || '',
        colors: colorIds, // only IDs
        sizes: product.sizes || [],
      })

      setSelectedColors(colorIds)
      setValue('colors', colorIds) // fixed

      setSelectedSizes(product.sizes || [])
      setSelectedCategoryId(product.category?._id || '')

      if (product.images?.length > 0) {
        const existingImages: UploadedImage[] = product.images.map(
          (imageUrl: string) => ({
            preview: imageUrl,
            isExisting: true,
          })
        )
        setUploadedImages(existingImages)
      }

      setIsDataLoaded(true)
    }
  }, [editId, singleProductData, reset, isDataLoaded, setValue])

  // Watch for category changes
  const watchedCategory = watch('category')

  // Update product types when category changes
  useEffect(() => {
    if (watchedCategory && categoriesData?.data) {
      const selectedCategory = categoriesData.data.find(
        (cat) => cat._id === watchedCategory
      )
      if (selectedCategory) {
        setAvailableProductTypes(selectedCategory.productType)
        setSelectedCategoryId(watchedCategory)

        // Only reset subcategory and product type if not in edit mode or category actually changed
        if (!editId || (editId && isDataLoaded)) {
          // const currentSubCategory = watch('subCategory')
          const currentProductType = watch('productType')

          // Reset only if we're not loading initial data
          if (isDataLoaded || !editId) {
            if (!selectedCategory.productType.includes(currentProductType)) {
              setValue('productType', '')
            }
            // Don't reset subcategory here, let it be handled by the subcategories effect
          }
        }
      }
    } else {
      setAvailableProductTypes([])
      if (!editId || isDataLoaded) {
        setSelectedCategoryId('')
        setValue('subCategory', '')
        setValue('productType', '')
      }
    }
  }, [watchedCategory, categoriesData, setValue, editId, isDataLoaded, watch])

  // Image upload preview
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return

    const files = Array.from(e.target.files)
    const newImages: UploadedImage[] = files.map((file) => ({
      file,
      preview: URL.createObjectURL(file),
      isExisting: false,
    }))

    setUploadedImages((prev) => [...prev, ...newImages])
  }

  // Remove uploaded image
  const removeImage = (index: number) => {
    const imageToRemove = uploadedImages[index]

    // Revoke object URL only for new uploads, not existing images
    if (!imageToRemove.isExisting && imageToRemove.preview) {
      URL.revokeObjectURL(imageToRemove.preview)
    }

    setUploadedImages((prev) => prev.filter((_, i) => i !== index))
  }

  // Handle size selection
  const handleSizeChange = (size: string) => {
    const newSizes = selectedSizes.includes(size)
      ? selectedSizes.filter((s) => s !== size)
      : [...selectedSizes, size]

    setSelectedSizes(newSizes)
    setValue('sizes', newSizes)
  }

  const onSubmit = (data: ProductFormData) => {
    console.log('products form data', data)

    if (editId) {
      // Update existing product
      const updateData = {
        title: data.title,

        msrp: data.msrp,
        moq: data.moq,
        unitPrice: data.unitPrice,
        discountPrice: data.discountPrice,
        quantity: data.quantity,
        description: data.description,
        // action: data.action,
        category: data.category,
        subCategory: data.subCategory,
        productType: data.productType,
        brand: data.brand,
        colors: selectedColors, // use state
        sizes: data.sizes,
      }

      updateProduct({
        productId: editId,
        data: updateData,
      })
    } else {
      // Add new product
      const formData = new FormData()

      const payload = {
        title: data.title,

        msrp: data.msrp,
        moq: data.moq,
        unitPrice: data.unitPrice,
        discountPrice: data.discountPrice,
        quantity: data.quantity,
        description: data.description,
        // action: data.action,
        category:
          typeof data.category === 'string' ? data.category : data.category._id,
        subCategory:
          typeof data.subCategory === 'string'
            ? data.subCategory
            : data.subCategory._id,
        productType: data.productType,
        brand: data.brand,
        colors: selectedColors, // use state
        sizes: data.sizes,
      }

      formData.append('data', JSON.stringify(payload))

      // Append only new images
      uploadedImages.forEach((image) => {
        if (image.file && !image.isExisting) {
          formData.append('images', image.file)
        }
      })

      addProduct(formData)
    }
  }

  // Reset function
  const resetForm = () => {
    reset(defaultFormValues)
    setUploadedImages([])
    setSelectedColors([])
    setSelectedSizes([])
    setSelectedCategoryId('')
    setAvailableProductTypes([])
    setIsDataLoaded(false)

    // Clean up image preview URLs
    uploadedImages.forEach((image) => {
      if (!image.isExisting && image.preview) {
        URL.revokeObjectURL(image.preview)
      }
    })
  }

  // Show loading state when fetching product data
  if (editId && singleProductLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="flex items-center gap-2">
          <Loader2 className="w-6 h-6 animate-spin" />
          <span>Loading product data...</span>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen ">
      <div>
        <div className="pb-5">
          {/* Header */}
          <div className="flex justify-between items-center">
            <h1 className="text-2xl font-semibold text-gray-900">
              Add Products
            </h1>
            <div className="flex gap-2">
              <Button
                type="button"
                onClick={resetForm}
                variant="outline"
                size="sm"
                className="h-[50px] px-6"
                disabled={isPending}
              >
                Reset Form
              </Button>
              <Button
                onClick={handleSubmit(onSubmit)}
                size="sm"
                className="bg-[#797068] hover:bg-[#3a3129] text-white text-base h-[50px] px-6"
                disabled={isPending}
              >
                {isPending ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Publishing...
                  </>
                ) : (
                  'Publish Product'
                )}
              </Button>
            </div>
          </div>

          {/* Breadcrumb */}
          <div className="flex items-center text-sm text-gray-500 mb-6">
            <span>Dashboard</span>
            <ChevronRight className="w-4 h-4 mx-2" />
            <span>Products List</span>
            <ChevronRight className="w-4 h-4 mx-2" />
            <span className="text-gray-900">Add Products</span>
          </div>
        </div>

        <form onSubmit={handleSubmit(onSubmit)}>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Left Column */}
            <div className="lg:col-span-2 space-y-6">
              {/* Title */}
              <Card className="bg-transparent shadow-none">
                <CardContent>
                  <Label
                    htmlFor="title"
                    className="text-base font-semibold text-gray-900 mb-2 block"
                  >
                    Add Title
                  </Label>
                  <Input
                    id="title"
                    placeholder="Add your title..."
                    {...register('title')}
                    className="w-full h-[50px] border border-[#B6B6B6]"
                  />
                  {errors.title && (
                    <p className="text-red-500 text-sm mt-1">
                      {errors.title.message}
                    </p>
                  )}
                </CardContent>
              </Card>

              {/* Vendor Name */}
              {/* <Card>
                <CardContent>
                  <Label
                    htmlFor="vendor"
                    className="text-base font-semibold text-gray-900 mb-2 block"
                  >
                    Add Vendor Name
                  </Label>
                  <Input
                    id="vendor"
                    placeholder="Add vendor name..."
                    {...register('vendorName')}
                    className="w-full h-[50px] border border-[#B6B6B6]"
                  />
                  {errors.vendorName && (
                    <p className="text-red-500 text-sm mt-1">
                      {errors.vendorName.message}
                    </p>
                  )}
                </CardContent>
              </Card> */}

              {/* MSRP and MOQ */}
              <Card className="bg-transparent shadow-none">
                <CardContent>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <Label htmlFor="msrp" className="font-semibold pb-2">
                        MSRP
                      </Label>
                      <Input
                        id="msrp"
                        type="number"
                        step="0.01"
                        placeholder="Manufacturer's Suggested Retail Price..."
                        {...register('msrp', { valueAsNumber: true })}
                        className="w-full h-[50px] border border-[#B6B6B6]"
                      />
                      {errors.msrp && (
                        <p className="text-red-500 text-sm mt-1">
                          {errors.msrp.message}
                        </p>
                      )}
                    </div>
                    <div>
                      <Label htmlFor="moq" className="font-semibold pb-2">
                        MOQ
                      </Label>
                      <Input
                        id="moq"
                        type="number"
                        placeholder="Minimum Order Quantity..."
                        {...register('moq', { valueAsNumber: true })}
                        className="w-full h-[50px] border border-[#B6B6B6]"
                      />
                      {errors.moq && (
                        <p className="text-red-500 text-sm mt-1">
                          {errors.moq.message}
                        </p>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Price and Quantity */}
              <Card className="bg-transparent shadow-none">
                <CardContent>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                      <Label htmlFor="unitPrice" className="font-semibold pb-2">
                        Unit Price
                      </Label>
                      <Input
                        id="unitPrice"
                        type="number"
                        step="0.01"
                        placeholder="Price per unit..."
                        {...register('unitPrice', { valueAsNumber: true })}
                        className="w-full h-[50px] border border-[#B6B6B6]"
                      />
                      {errors.unitPrice && (
                        <p className="text-red-500 text-sm mt-1">
                          {errors.unitPrice.message}
                        </p>
                      )}
                    </div>
                    <div>
                      <Label
                        htmlFor="discountPrice"
                        className="font-semibold pb-2"
                      >
                        Discount Price
                      </Label>
                      <Input
                        id="discountPrice"
                        type="number"
                        step="0.01"
                        placeholder="Discount price (optional)..."
                        {...register('discountPrice', { valueAsNumber: true })}
                        className="w-full h-[50px] border border-[#B6B6B6]"
                      />
                      {errors.discountPrice && (
                        <p className="text-red-500 text-sm mt-1">
                          {errors.discountPrice.message}
                        </p>
                      )}
                    </div>
                    <div>
                      <Label htmlFor="quantity" className="font-semibold pb-2">
                        Quantity
                      </Label>
                      <Input
                        id="quantity"
                        type="number"
                        placeholder="Add Quantity..."
                        {...register('quantity', { valueAsNumber: true })}
                        className="w-full h-[50px] border border-[#B6B6B6]"
                      />
                      {errors.quantity && (
                        <p className="text-red-500 text-sm mt-1">
                          {errors.quantity.message}
                        </p>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Description */}
              <Card className="bg-transparent shadow-none">
                <CardContent>
                  <Label className="font-semibold pb-3">Description</Label>
                  <TiptapEditor
                    content={watch('description')}
                    onChange={(content) => setValue('description', content)}
                  />
                  {errors.description && (
                    <p className="text-red-500 text-sm mt-1">
                      {errors.description.message}
                    </p>
                  )}
                </CardContent>
              </Card>

              {/* Colors */}
              <Card className="bg-transparent shadow-none">
                <CardContent>
                  <Label className="font-semibold mb-3 block">Colors</Label>

                  {colorsLoading ? (
                    <p className="text-gray-500 text-sm">Loading colors...</p>
                  ) : colorData?.data?.data?.length ? (
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                      {colorData.data.data.map((clr) => {
                        const isSelected = selectedColors.includes(clr._id)
                        return (
                          <div
                            key={clr._id}
                            onClick={() => {
                              const newColors = isSelected
                                ? selectedColors.filter((c) => c !== clr._id)
                                : [...selectedColors, clr._id]

                              setSelectedColors(newColors)
                              setValue('colors', newColors)
                            }}
                            className={`flex items-center gap-2 p-2 border rounded cursor-pointer ${
                              isSelected
                                ? 'bg-gray-100 border-gray-400'
                                : 'border-gray-200'
                            }`}
                          >
                            <span
                              className="w-4 h-4 rounded-full border"
                              style={{ background: clr.code }}
                            />
                            <span className="text-sm">{clr.name}</span>
                            {isSelected && (
                              <span className="ml-auto text-green-600 font-bold">
                                ✓
                              </span>
                            )}
                          </div>
                        )
                      })}
                    </div>
                  ) : (
                    <p className="text-gray-500 text-sm">No colors available</p>
                  )}

                  {/* Validation error */}
                  {errors.colors && (
                    <p className="text-red-500 text-sm mt-2">
                      {errors.colors.message}
                    </p>
                  )}

                  {/* Selected preview */}
                  {selectedColors.length > 0 &&
                    colorData?.data?.data?.length && (
                      <div className="flex gap-2 flex-wrap mt-3">
                        {selectedColors.map((colorId) => {
                          const clr = colorData.data.data.find(
                            (c) => c._id === colorId
                          )
                          return clr ? (
                            <span
                              key={colorId}
                              className="flex items-center gap-1 text-sm border px-2 py-1 rounded"
                            >
                              <span
                                className="w-3 h-3 rounded-full"
                                style={{ background: clr.code }}
                              />
                              {clr.name}
                            </span>
                          ) : null
                        })}
                      </div>
                    )}
                </CardContent>
              </Card>

              {/* Sizes */}
              <Card className="bg-transparent shadow-none">
                <CardContent>
                  <Label className="font-semibold mb-4 block">Sizes</Label>
                  <div className="flex flex-wrap gap-2">
                    {sizeOptions.map((size) => (
                      <div key={size} className="flex items-center space-x-2">
                        <Checkbox
                          id={`size-${size}`}
                          checked={selectedSizes.includes(size)}
                          onCheckedChange={() => handleSizeChange(size)}
                        />
                        <Label htmlFor={`size-${size}`} className="text-sm">
                          {size}
                        </Label>
                      </div>
                    ))}
                  </div>
                  {errors.sizes && (
                    <p className="text-red-500 text-sm mt-2">
                      {errors.sizes.message}
                    </p>
                  )}
                </CardContent>
              </Card>
            </div>

            {/* Right Column */}
            <div className="space-y-2">
              {/* Status */}
              {/* <Card>
                <CardContent className="p-6">
                  <RadioGroup
                    value={watch('action')}
                    onValueChange={(value) =>
                      setValue('action', value as 'inactive' | 'active')
                    }
                    className="flex gap-6"
                  >
                    <div className="flex items-center space-x-2">
                      <RadioGroupItem value="inactive" id="inactive" />
                      <Label htmlFor="inactive">Inactive</Label>
                    </div>
                    <div className="flex items-center space-x-2">
                      <RadioGroupItem value="active" id="active" />
                      <Label htmlFor="active">Active</Label>
                    </div>
                  </RadioGroup>
                </CardContent>
              </Card> */}

              {/* Category */}
              <Card className="bg-transparent shadow-none">
                <CardContent className="p-6">
                  <Label className="font-semibold mb-2 block">Category</Label>
                  <Select
                    value={watch('category')}
                    onValueChange={(value) => setValue('category', value)}
                    disabled={categoriesLoading}
                  >
                    <SelectTrigger className="w-full h-[50px] border">
                      <SelectValue
                        placeholder={
                          categoriesLoading
                            ? 'Loading categories...'
                            : 'Select a Category'
                        }
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {categoriesData?.data?.map((category) => (
                        <SelectItem key={category._id} value={category._id}>
                          {category.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {errors.category && (
                    <p className="text-red-500 text-sm mt-1">
                      {errors?.category.message as string}
                    </p>
                  )}
                </CardContent>
              </Card>

              {/* SubCategory */}
              <Card className="bg-transparent shadow-none">
                <CardContent className="p-6">
                  <Label className="font-semibold mb-2 block">
                    SubCategory
                  </Label>
                  <Select
                    value={watch('subCategory')}
                    onValueChange={(value) => setValue('subCategory', value)}
                    disabled={!selectedCategoryId || subCategoriesLoading}
                  >
                    <SelectTrigger className="w-full h-[50px] border">
                      <SelectValue
                        placeholder={
                          !selectedCategoryId
                            ? 'Select a category first'
                            : subCategoriesLoading
                            ? 'Loading subcategories...'
                            : 'Select a SubCategory'
                        }
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {subCategoriesData?.data?.subCategories?.map(
                        (subCategory) => (
                          <SelectItem
                            key={subCategory._id}
                            value={subCategory._id}
                          >
                            {subCategory.name}
                          </SelectItem>
                        )
                      )}
                    </SelectContent>
                  </Select>
                  {errors.subCategory && (
                    <p className="text-red-500 text-sm mt-1">
                      {errors.subCategory.message as string}
                    </p>
                  )}
                </CardContent>
              </Card>

              {/* Product Type */}
              <Card className="bg-transparent shadow-none">
                <CardContent className="p-6">
                  <Label className="font-semibold mb-2 block">
                    Product Type
                  </Label>
                  <Select
                    value={watch('productType')}
                    onValueChange={(value) => setValue('productType', value)}
                    disabled={availableProductTypes.length === 0}
                  >
                    <SelectTrigger className="w-full h-[50px] border">
                      <SelectValue
                        placeholder={
                          availableProductTypes.length === 0
                            ? 'Select a category first'
                            : 'Select Product Type'
                        }
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {availableProductTypes.map((productType) => (
                        <SelectItem key={productType} value={productType}>
                          {productType}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {errors.productType && (
                    <p className="text-red-500 text-sm mt-1">
                      {errors.productType.message}
                    </p>
                  )}
                </CardContent>
              </Card>

              {/* Brand */}
              <Card className="bg-transparent shadow-none">
                <CardContent className="p-6">
                  <Label className="font-semibold mb-2 block">Brand</Label>
                  <Input
                    placeholder="Enter brand name..."
                    {...register('brand')}
                    className="w-full h-[50px] border border-[#B6B6B6]"
                  />
                  {errors.brand && (
                    <p className="text-red-500 text-sm mt-1">
                      {errors.brand.message}
                    </p>
                  )}
                </CardContent>
              </Card>

              {/* Product Images */}
              <Card className="bg-transparent shadow-none">
                <CardContent className="p-6">
                  <Label className="font-medium mb-4 block">
                    Add Product Image
                  </Label>

                  {/* Upload */}
                  <div className="border-2 border-dashed rounded-lg p-8 text-center mb-4">
                    <div className="flex flex-col items-center">
                      <Upload className="w-8 h-8 text-gray-400 mb-2" />
                      <p className="text-sm text-gray-500 mb-1">
                        Note: Upload Max 200×200 pixels
                      </p>
                      <p className="text-sm text-gray-500">Formats PNG</p>
                      <input
                        type="file"
                        multiple
                        accept="image/*"
                        onChange={handleImageUpload}
                        className="hidden"
                        id="image-upload"
                      />
                      <Button
                        type="button"
                        variant="outline"
                        className="mt-4"
                        onClick={() =>
                          document.getElementById('image-upload')?.click()
                        }
                      >
                        Upload Image
                      </Button>
                    </div>
                  </div>

                  {/* Preview */}
                  <div className="grid grid-cols-4 gap-2">
                    {uploadedImages.map((image, index) => (
                      <div
                        key={index}
                        className="aspect-square border rounded-lg overflow-hidden relative"
                      >
                        <Image
                          width={300}
                          height={300}
                          src={image.preview}
                          alt={`Upload ${index + 1}`}
                          className="w-full h-full object-cover"
                        />
                        <button
                          type="button"
                          onClick={() => removeImage(index)}
                          className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </div>
                    ))}
                    {Array.from({
                      length: Math.max(0, 4 - uploadedImages.length),
                    }).map((_, index) => (
                      <div
                        key={`empty-${index}`}
                        className="aspect-square border flex items-center justify-center bg-gray-50 rounded-lg"
                      >
                        <ImageIcon className="w-6 h-6 text-gray-300" />
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </form>
      </div>
    </div>
  )
}
